    align-items: center;
    justify-content: center;
    transition: box-shadow 0.2s ease;
}

.cms-shadow-custom__preview-text {
    font-size: 9px;
    color: #94a3b8;
    font-weight: 500;
}

/* ═══════════════════════════════════════════════════════════════
   §154 — Filter Slider Enhanced
   Labeled range slider for image/section filters
   ═══════════════════════════════════════════════════════════════ */

.cms-filter-slider {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.cms-filter-slider__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.cms-filter-slider__label {
    font-size: 9px;
    font-weight: 500;
    color: #64748b;
}

.cms-filter-slider__value {
    font-size: 9px;
    font-family: 'JetBrains Mono', monospace;
    color: #334155;
    font-weight: 600;
    min-width: 32px;
    text-align: right;
}

.cms-filter-slider__track {
    position: relative;
    height: 20px;
    display: flex;
    align-items: center;
}

.cms-filter-slider__input {
    width: 100%;
    height: 4px;
    border-radius: 2px;
    -webkit-appearance: none;
    appearance: none;
    background: rgba(226, 232, 240, 0.6);
    outline: none;
}

.cms-filter-slider__input::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: white;
    border: 2px solid #6366f1;
    box-shadow: 0 1px 4px rgba(99, 102, 241, 0.25);
    cursor: pointer;
    transition: all 0.15s ease;
}

.cms-filter-slider__input::-webkit-slider-thumb:hover {
    transform: scale(1.15);
    box-shadow: 0 2px 6px rgba(99, 102, 241, 0.35);
}

.cms-filter-slider__input::-moz-range-thumb {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: white;
    border: 2px solid #6366f1;
    box-shadow: 0 1px 4px rgba(99, 102, 241, 0.25);
    cursor: pointer;
}

/* Variant colors */
.cms-filter-slider--amber .cms-filter-slider__input::-webkit-slider-thumb {
    border-color: #d97706;
}

.cms-filter-slider--emerald .cms-filter-slider__input::-webkit-slider-thumb {
    border-color: #059669;
}

.cms-filter-slider--rose .cms-filter-slider__input::-webkit-slider-thumb {
    border-color: #e11d48;
}

.cms-filter-slider--purple .cms-filter-slider__input::-webkit-slider-thumb {
    border-color: #7c3aed;
}

/* ═══════════════════════════════════════════════════════════════
   §155 — Spacing Box Model Enhanced
   Interactive box model with color-coded layers
   ═══════════════════════════════════════════════════════════════ */

.cms-box-model-v2 {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 8px;
    border-radius: 10px;
    background: linear-gradient(135deg, rgba(248, 250, 252, 0.9), rgba(241, 245, 249, 0.7));
    border: 1px solid rgba(226, 232, 240, 0.4);
}

.cms-box-model-v2__layer {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    padding: 6px;
    border-radius: 6px;
    position: relative;
}

.cms-box-model-v2__layer--margin {
    background: rgba(251, 191, 36, 0.08);
    border: 1px dashed rgba(251, 191, 36, 0.3);
}

.cms-box-model-v2__layer--padding {
    background: rgba(34, 197, 94, 0.08);
    border: 1px dashed rgba(34, 197, 94, 0.3);
}

.cms-box-model-v2__layer--content {
    background: rgba(99, 102, 241, 0.08);
    border: 1px solid rgba(99, 102, 241, 0.2);
    min-height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.cms-box-model-v2__layer-label {
    font-size: 7px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    position: absolute;
    top: 2px;
    left: 4px;
}

.cms-box-model-v2__layer-label--margin {
    color: #d97706;
}

.cms-box-model-v2__layer-label--padding {
    color: #16a34a;
}

.cms-box-model-v2__layer-label--content {
    color: #6366f1;
}

.cms-box-model-v2__inputs {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    gap: 4px;
    align-items: center;
    width: 100%;
}

.cms-box-model-v2__input {
    width: 100%;
    padding: 3px 6px;
    border-radius: 4px;
    border: 1px solid rgba(226, 232, 240, 0.5);
    background: white;
    font-size: 9px;
    font-family: 'JetBrains Mono', monospace;
    color: #334155;
    text-align: center;
    transition: all 0.15s ease;
}

.cms-box-model-v2__input:focus {
    outline: none;
    border-color: rgba(99, 102, 241, 0.4);
    box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.1);
}

.cms-box-model-v2__input--margin:focus {
    border-color: rgba(217, 119, 6, 0.4);
    box-shadow: 0 0 0 2px rgba(217, 119, 6, 0.1);
}

.cms-box-model-v2__input--padding:focus {
    border-color: rgba(22, 163, 74, 0.4);
    box-shadow: 0 0 0 2px rgba(22, 163, 74, 0.1);
}

.cms-box-model-v2__center {
    font-size: 8px;
    font-weight: 700;
    color: #94a3b8;
    padding: 2px 6px;
}

/* ═══════════════════════════════════════════════════════════════
   §156 — Transform Origin Visual Grid
   3x3 dot grid for transform origin selection
   ═══════════════════════════════════════════════════════════════ */

.cms-transform-origin-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 4px;
    width: fit-content;
    padding: 6px;
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.8);
    border: 1px solid rgba(226, 232, 240, 0.4);
}

.cms-transform-origin-dot {
    width: 28px;
    height: 28px;
    border-radius: 6px;
    border: 1px solid rgba(226, 232, 240, 0.6);
    background: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.15s ease;
    font-size: 10px;
    color: #94a3b8;
}

.cms-transform-origin-dot:hover {
    border-color: rgba(16, 185, 129, 0.3);
    background: rgba(236, 253, 245, 0.5);
    color: #059669;
    transform: scale(1.1);
}

.cms-transform-origin-dot--active {
    border-color: rgba(16, 185, 129, 0.5);
    background: rgba(236, 253, 245, 0.8);
    color: #059669;
    box-shadow: 0 0 0 1px rgba(16, 185, 129, 0.2);
}

.cms-transform-origin-dot__circle {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
    transition: all 0.15s ease;
}

.cms-transform-origin-dot--active .cms-transform-origin-dot__circle {
    width: 8px;
    height: 8px;
    box-shadow: 0 0 4px rgba(16, 185, 129, 0.4);
}

/* ═══════════════════════════════════════════════════════════════
   §157 — Animation Timeline Enhanced
   Visual timeline with playhead and keyframe markers
   ═══════════════════════════════════════════════════════════════ */

.cms-anim-timeline-v2 {
    position: relative;
    padding: 8px;
    border-radius: 8px;
    background: linear-gradient(135deg, rgba(139, 92, 246, 0.04), rgba(99, 102, 241, 0.04));
    border: 1px solid rgba(139, 92, 246, 0.12);
}

.cms-anim-timeline-v2__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 6px;
}

.cms-anim-timeline-v2__title {
    font-size: 8px;
    font-weight: 700;
    color: #7c3aed;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    display: flex;
    align-items: center;
    gap: 4px;
}

.cms-anim-timeline-v2__controls {
    display: flex;
    gap: 4px;
}

.cms-anim-timeline-v2__btn {
    width: 20px;
    height: 20px;
    border-radius: 4px;
    border: 1px solid rgba(139, 92, 246, 0.2);
    background: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #7c3aed;
    transition: all 0.15s ease;
}

.cms-anim-timeline-v2__btn:hover {
    background: rgba(139, 92, 246, 0.08);
    border-color: rgba(139, 92, 246, 0.4);
}

.cms-anim-timeline-v2__track {
    position: relative;
    height: 24px;
    border-radius: 4px;
    background: rgba(248, 250, 252, 0.8);
    border: 1px solid rgba(226, 232, 240, 0.4);
    overflow: hidden;
}

.cms-anim-timeline-v2__bar {
    position: absolute;
    top: 2px;
    bottom: 2px;
    left: 2px;
    border-radius: 3px;
    background: linear-gradient(90deg, rgba(139, 92, 246, 0.3), rgba(99, 102, 241, 0.3));
    transition: width 0.2s ease;
}

.cms-anim-timeline-v2__playhead {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 2px;
    background: #7c3aed;
    border-radius: 1px;
    transition: left 0.2s ease;
}

.cms-anim-timeline-v2__playhead::before {
    content: '';
    position: absolute;
    top: -2px;
    left: -3px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #7c3aed;
    box-shadow: 0 1px 3px rgba(124, 58, 237, 0.3);
}

.cms-anim-timeline-v2__labels {
    display: flex;
    justify-content: space-between;
    margin-top: 4px;
}

.cms-anim-timeline-v2__label {
    font-size: 7px;
    font-family: 'JetBrains Mono', monospace;
    color: #94a3b8;
}

/* ═══════════════════════════════════════════════════════════════
   §158 — Canvas Toolbar Enhanced
   Professional toolbar with device switcher, grid, rulers
