.cms-toolbar-group__btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 4px;
    border: none;
    background: transparent;
    cursor: pointer;
    color: #64748b;
    transition: all 0.15s ease;
}

.cms-toolbar-group__btn:hover {
