/* ═══════════════════════════════════════════════════════════════
   §160 — Animation Presets Grid v2
   ═══════════════════════════════════════════════════════════════ */

.cms-anim-presets-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 4px;
}

.cms-anim-preset-btn {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    padding: 5px 2px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    color: #64748b;
    background: transparent;
    cursor: pointer;
    transition: all 0.15s ease;
    position: relative;
    overflow: hidden;
}

.cms-anim-preset-btn:hover {
    border-color: #c4b5fd;
    background: rgba(139, 92, 246, 0.04);
    color: #7c3aed;
}

.cms-anim-preset-btn:hover .cms-anim-preset-btn__icon {
    transform: scale(1.15);
}

.cms-anim-preset-btn--active {
    border-color: #c4b5fd;
    background: rgba(139, 92, 246, 0.08);
