.cms-layout-display-btn:hover {
    border-color: #93c5fd;
    background: rgba(59, 130, 246, 0.04);
    color: #2563eb;
}

.cms-layout-display-btn--active {
    border-color: #93c5fd;
    background: rgba(59, 130, 246, 0.08);
    color: #2563eb;
    box-shadow: 0 1px 3px rgba(59, 130, 246, 0.12);
}

.cms-layout-display-btn__icon {
    font-size: 14px;
