}

.cms-canvas-scrollarea::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

.cms-canvas-scrollarea::-webkit-scrollbar-track {
    background: transparent;
    border-radius: 4px;
}

.cms-canvas-scrollarea::-webkit-scrollbar-thumb {
    background: rgba(148, 163, 184, 0.35);
    border-radius: 4px;
    border: 2px solid transparent;
    background-clip: content-box;
    transition: background 0.2s ease;
}

.cms-canvas-scrollarea::-webkit-scrollbar-thumb:hover {
    background: rgba(148, 163, 184, 0.6);
    background-clip: content-box;
}

.cms-canvas-scrollarea::-webkit-scrollbar-corner {
    background: transparent;
}

/* Scrollbar corner indicator */
.cms-canvas-scrollarea::after {
    content: '';
    position: absolute;
    bottom: 0;
    right: 0;
    width: 8px;
    height: 8px;
    background: rgba(148, 163, 184, 0.15);
    border-radius: 0 0 4px 0;
}

