/* ═══════════════════════════════════════════════════════════
   §174. CANVAS BACKGROUND — Figma-style adaptive dot grid
   Background qui s'adapte au niveau de zoom
   ═══════════════════════════════════════════════════════════ */
.cms-canvas-bg-pro {
    position: relative;
    background-color: #f1f5f9;
    transition: background-color 0.3s ease;
}

.cms-canvas-bg-pro--dark {
    background-color: #0c1222;
}

/* Dot grid pattern — 3 layers for depth */
.cms-canvas-bg-pro::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image:
        radial-gradient(circle, rgba(148,163,184,0.18) 0.8px, transparent 0.8px),
        radial-gradient(circle, rgba(148,163,184,0.06) 0.5px, transparent 0.5px),
        radial-gradient(ellipse at 50% 0%, rgba(99,102,241,0.03) 0%, transparent 70%);
    background-size: 24px 24px, 12px 12px, 100% 100%;
    pointer-events: none;
    z-index: 0;
    transition: opacity 0.4s ease;
}

.cms-canvas-bg-pro--dark::before {
    background-image:
        radial-gradient(circle, rgba(148,163,184,0.06) 0.8px, transparent 0.8px),
        radial-gradient(circle, rgba(148,163,184,0.025) 0.5px, transparent 0.5px),
        radial-gradient(ellipse at 50% 0%, rgba(99,102,241,0.02) 0%, transparent 70%);
}

/* Zoom-adaptive density — hide dots at low zoom */
.cms-canvas-bg-pro[data-zoom-low]::before {
    background-image:
        radial-gradient(circle, rgba(148,163,184,0.12) 0.6px, transparent 0.6px);
    background-size: 48px 48px;
}

/* Crosshair center guides — Figma-style */
.cms-canvas-bg-pro__guides {
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: 1;
    opacity: 0.4;
    transition: opacity 0.3s ease;
}

.cms-canvas-bg-pro__guides--visible {
    opacity: 0.7;
}

.cms-canvas-bg-pro__guide-h {
    position: absolute;
    left: 0;
    right: 0;
    height: 1px;
    top: 50%;
    background: repeating-linear-gradient(
        90deg,
        rgba(59,130,246,0.25) 0px,
        rgba(59,130,246,0.25) 4px,
        transparent 4px,
        transparent 8px
    );
}

.cms-canvas-bg-pro__guide-v {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 1px;
    left: 50%;
    background: repeating-linear-gradient(
        180deg,
        rgba(59,130,246,0.25) 0px,
        rgba(59,130,246,0.25) 4px,
        transparent 4px,
        transparent 8px
    );
}

/* ═══════════════════════════════════════════════════════════
   §175. CANVAS HOVER TOOLBAR — Semantic classes
   Migration depuis Tailwind inline
   ═══════════════════════════════════════════════════════════ */
.cms-hover-toolbar {
    position: absolute;
    z-index: 40;
    pointer-events: auto;
    animation: cmsToolbarFadeIn 0.15s ease-out;
}

@keyframes cms-toolbar-fade-in {
    from { opacity: 0; transform: translateX(-50%) translateY(4px); }
    to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

.cms-hover-toolbar__inner {
    display: flex;
    align-items: center;
    gap: 1px;
    border-radius: 8px;
    border: 1px solid rgba(226,232,240,0.8);
    background: rgba(255,255,255,0.95);
    padding: 2px 4px 2px 2px;
    box-shadow: 0 4px 16px rgba(0,0,0,0.08), 0 1px 3px rgba(0,0,0,0.04);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}

.cms-hover-toolbar__label {
    padding: 2px 6px;
    font-size: 9px;
    font-weight: 600;
    color: #64748b;
    white-space: nowrap;
    border-right: 1px solid #f1f5f9;
    margin-right: 2px;
    max-width: 100px;
    overflow: hidden;
    text-overflow: ellipsis;
}

.cms-hover-toolbar__sep {
    width: 1px;
    height: 14px;
    background: #e2e8f0;
    margin: 0 2px;
    flex-shrink: 0;
}

/* Action button within hover toolbar */
.cms-hover-toolbar__btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    border-radius: 6px;
    border: none;
    background: transparent;
    color: #94a3b8;
    cursor: pointer;
    transition: all 0.12s ease;
}

.cms-hover-toolbar__btn:hover {
    color: #475569;
}

.cms-hover-toolbar__btn--indigo:hover {
    background: rgba(99,102,241,0.08);
    color: #6366f1;
}

.cms-hover-toolbar__btn--purple:hover {
    background: rgba(168,85,247,0.08);
    color: #a855f7;
}

.cms-hover-toolbar__btn--blue:hover {
    background: rgba(59,130,246,0.08);
    color: #3b82f6;
}

.cms-hover-toolbar__btn--emerald:hover {
    background: rgba(16,185,129,0.08);
    color: #10b981;
}

.cms-hover-toolbar__btn--amber:hover {
    background: rgba(245,158,11,0.08);
    color: #f59e0b;
}

.cms-hover-toolbar__btn--active {
    background: rgba(99,102,241,0.1);
    color: #6366f1;
}

.cms-hover-toolbar__btn svg {
    width: 12px;
    height: 12px;
}

/* Expanded dropdown menu */
.cms-hover-toolbar__menu {
    position: absolute;
    right: 0;
    top: 100%;
    margin-top: 4px;
    min-width: 160px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    background: rgba(255,255,255,0.98);
    padding: 4px 0;
    box-shadow: 0 8px 24px rgba(0,0,0,0.12);
    backdrop-filter: blur(16px);
    z-index: 50;
    animation: cmsScaleEnter 0.12s ease-out;
}

.cms-hover-toolbar__menu-item {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    padding: 6px 10px;
    font-size: 10px;
    color: #475569;
    border: none;
    background: transparent;
    cursor: pointer;
    transition: background 0.1s ease;
}

.cms-hover-toolbar__menu-item:hover {
