}

.cms-hover-toolbar__menu-item--danger:hover {
    background: #fef2f2;
    color: #dc2626;
}

.cms-hover-toolbar__menu-item svg {
    width: 12px;
    height: 12px;
    flex-shrink: 0;
}

.cms-hover-toolbar__menu-sep {
    height: 1px;
    background: #f1f5f9;
    margin: 2px 0;
}

/* ═══════════════════════════════════════════════════════════
   §176. TOOLBAR SECONDAIRE ENHANCED — Semantic classes
   ═══════════════════════════════════════════════════════════ */
.cms-toolbar-pro {
    display: flex;
    align-items: center;
    gap: 4px;
